document.addEventListener('DOMContentLoaded', function () {

  /* =========================================================
     FUNCIÓN AUXILIAR — enableAnalytics
     Declarada antes de las funciones init* para que
     initCookieBanner pueda referenciarla sin depender de hoisting.
  ========================================================= */
  function enableAnalytics() {
    window.dataLayer = window.dataLayer || [];
    function gtag() { window.dataLayer.push(arguments); }
    gtag('js', new Date());
    gtag('config', 'G-XXXXXXXXXX');

    const script = document.createElement('script');
    script.async = true;
    script.src = 'https://www.googletagmanager.com/gtag/js?id=G-XXXXXXXXXX';
    document.head.appendChild(script);
  }

  /* =========================================================
     PASO 2 — initRouter
     Navegación SPA-like entre secciones Home / Historias / Noticias.
  ========================================================= */
  function initRouter() {
    const navLinks = document.querySelectorAll('.nav-link');
    const sections = document.querySelectorAll('.section-body');

    function activateSection(targetId) {
      sections.forEach(function (sec) { sec.hidden = true; });
      navLinks.forEach(function (lnk) { lnk.classList.remove('is-active'); });

      const targetSection = document.getElementById(targetId);
      if (targetSection) { targetSection.hidden = false; }

      const activeLinks = document.querySelectorAll('.nav-link[data-target="' + targetId + '"]');
      activeLinks.forEach(function (lnk) { lnk.classList.add('is-active'); });

      if (targetSection) {
        targetSection.scrollIntoView({ behavior: 'smooth', block: 'start' });
      }
    }

    navLinks.forEach(function (link) {
      link.addEventListener('click', function (e) {
        e.preventDefault();
        const targetId = link.dataset.target;
        if (targetId) {
          activateSection(targetId);
          /* FIX #3: Cerrar el menú móvil al navegar a una sección */
          const mainNav = document.getElementById('main-nav');
          const navToggle = document.querySelector('.nav-toggle');
          if (mainNav && mainNav.classList.contains('is-open')) {
            mainNav.classList.remove('is-open');
            if (navToggle) {
              navToggle.setAttribute('aria-expanded', 'false');
              navToggle.setAttribute('aria-label', 'Abrir menú de navegación');
            }
          }
        }
      });
    });

    activateSection('section-home');
  }

  /* =========================================================
     PASO 3 — initMobileNav
     FIX #3: Implementa la lógica del botón hamburguesa para
     móvil. Escucha el click en .nav-toggle, agrega/remueve
     la clase 'is-open' en #main-nav y actualiza aria-expanded.
  ========================================================= */
  function initMobileNav() {
    const navToggle = document.querySelector('.nav-toggle');
    const mainNav = document.getElementById('main-nav');

    if (!navToggle || !mainNav) { return; }

    navToggle.addEventListener('click', function () {
      const isOpen = mainNav.classList.contains('is-open');

      if (isOpen) {
        mainNav.classList.remove('is-open');
        navToggle.setAttribute('aria-expanded', 'false');
        navToggle.setAttribute('aria-label', 'Abrir menú de navegación');
      } else {
        mainNav.classList.add('is-open');
        navToggle.setAttribute('aria-expanded', 'true');
        navToggle.setAttribute('aria-label', 'Cerrar menú de navegación');
      }
    });
  }

  /* =========================================================
     PASO 4 — initFaq
     Acordeón exclusivo: solo 1 item abierto a la vez.
  ========================================================= */
  function initFaq() {
    const faqSection = document.getElementById('faq-section');
    if (!faqSection) { return; }

    const faqItems = faqSection.querySelectorAll('.faq-item');

    function closeAllItems() {
      faqItems.forEach(function (item) {
        item.classList.remove('is-open');
        const answer = item.querySelector('.faq-answer');
        if (answer) { answer.hidden = true; }
        const question = item.querySelector('.faq-question');
        if (question) { question.setAttribute('aria-expanded', 'false'); }
      });
    }

    faqItems.forEach(function (item) {
      const question = item.querySelector('.faq-question');
      if (!question) { return; }

      question.addEventListener('click', function () {
        const isCurrentlyOpen = item.classList.contains('is-open');
        closeAllItems();
        if (!isCurrentlyOpen) {
          item.classList.add('is-open');
          const answer = item.querySelector('.faq-answer');
          if (answer) { answer.hidden = false; }
          question.setAttribute('aria-expanded', 'true');
        }
      });
    });
  }

  /* =========================================================
     PASO 5 — initCookieBanner
     Consentimiento de cookies con persistencia en localStorage.
     Activa analytics si el consentimiento previo fue 'accepted'.
  ========================================================= */
  function initCookieBanner() {
    const banner    = document.getElementById('cookie-banner');
    const acceptBtn = document.getElementById('cookie-accept-btn');
    const rejectBtn = document.getElementById('cookie-reject-btn');

    if (!banner || !acceptBtn || !rejectBtn) { return; }

    if (localStorage.getItem('cookie_consent')) {
      banner.hidden = true;
      if (localStorage.getItem('cookie_consent') === 'accepted') {
        enableAnalytics();
      }
      return;
    }

    /* Mostrar el banner: quitar hidden primero, luego añadir .is-visible
       en el siguiente frame para que la transición CSS de opacidad se dispare.
       FIX #1 y #2: Ahora que el elemento tiene la clase 'cookie-banner' en el HTML,
       .cookie-banner.is-visible resuelve correctamente y la transición funciona. */
    banner.hidden = false;
    requestAnimationFrame(function () {
      banner.classList.add('is-visible');
    });

    acceptBtn.addEventListener('click', function () {
      localStorage.setItem('cookie_consent', 'accepted');
      banner.classList.remove('is-visible');
      banner.hidden = true;
      enableAnalytics();
    });

    rejectBtn.addEventListener('click', function () {
      localStorage.setItem('cookie_consent', 'rejected');
      banner.classList.remove('is-visible');
      banner.hidden = true;
    });
  }

  /* =========================================================
     PASO 6 — initAnalyticsStub
     Configura el stub inicial de gtag. No carga el script de red;
     eso lo hace enableAnalytics() condicionalmente.
  ========================================================= */
  function initAnalyticsStub() {
    window.dataLayer = window.dataLayer || [];
    function gtag() { window.dataLayer.push(arguments); }
    gtag('js', new Date());
    gtag('config', 'G-XXXXXXXXXX');
  }

  /* =========================================================
     ARRANQUE — Orden de inicialización obligatorio
  ========================================================= */
  initRouter();
  initMobileNav();
  initFaq();
  initCookieBanner();
  initAnalyticsStub();

});

historial_friccion_qa.feedback_entregado:
Se detectaron 3 violaciones críticas a las directivas del Tech Lead:

1. SCOPE DE FUNCIONES (CRÍTICO): Las funciones `enableAnalytics`, `initRouter`, `initFaq` e `initCookieBanner` están declaradas en el SCOPE GLOBAL del archivo, fuera del listener `DOMContentLoaded`. La directiva del Tech Lead es explícita: 'Cada función init* es privada al scope del listener. No las expongas en window.' y 'enableAnalytics() es una función auxiliar definida en el scope del DOMContentLoaded listener'. El código del Dev declara todas estas funciones como funciones de primer nivel del módulo, lo que las expone en el scope global (window.initRouter, window.initFaq, etc.), violando directamente la restricción de encapsulamiento.

2. LLAMADA FALTANTE A `initAnalyticsStub()` (CRÍTICO): La estructura base obligatoria definida por el Tech Lead exige exactamente:
   document.addEventListener('DOMContentLoaded', function () {
     initRouter();
     initFaq();
     initCookieBanner();
     initAnalyticsStub();
   });
   El código del Dev omite la llamada a `initAnalyticsStub()` y tampoco implementa la función `initAnalyticsStub()` en ninguna parte del archivo. El PASO 5 exige que exista esta función separada de `enableAnalytics()`.

3. FUNCIÓN `initAnalyticsStub()` NO IMPLEMENTADA (CRÍTICO): El PASO 5 define dos entidades distintas: `initAnalyticsStub()` (que se llama desde el DOMContentLoaded y configura el stub inicial) y `enableAnalytics()` (que se llama condicionalmente cuando el usuario acepta cookies). El Dev solo implementó `enableAnalytics()` pero omitió completamente `initAnalyticsStub()`, dejando incompleto el contrato de implementación del PASO 5.

Acciones requeridas para aprobación:
- Mover TODAS las funciones (enableAnalytics, initRouter, initFaq, initCookieBanner, initAnalyticsStub) al interior del callback de DOMContentLoaded.
- Implementar la función `initAnalyticsStub()` según el PASO 5.
- Agregar la llamada `initAnalyticsStub()` en la secuencia de inicialización del DOMContentLoaded.

PROBLEMA 1 — DUPLICACIÓN DE LÓGICA DE ANALYTICS (Defecto funcional): La función `initCookieBanner()` NO activa analytics cuando detecta consentimiento previo 'accepted' en localStorage. El código del Dev omitió el bloque condicional que el Tech Lead especificó explícitamente:

  // CORRECTO (según directiva PASO 4):
  if (localStorage.getItem('cookie_consent')) {
    banner.hidden = true;
    if (localStorage.getItem('cookie_consent') === 'accepted') {
      enableAnalytics(); // ← FALTA ESTA LLAMADA
    }
    return;
  }

  // LO QUE ENTREGÓ EL DEV:
  if (localStorage.getItem('cookie_consent')) {
    banner.hidden = true;
    return; // ← sale sin llamar enableAnalytics()
  }

Esto significa que un usuario que ya aceptó cookies en una visita anterior NO tendrá analytics activado al recargar la página. La función `initAnalyticsStub()` sí lo cubre, pero eso crea una dependencia implícita frágil: si alguien reordena las llamadas init* o elimina initAnalyticsStub(), el comportamiento se rompe silenciosamente. La directiva del Tech Lead es clara: initCookieBanner DEBE llamar enableAnalytics() en el bloque de consentimiento previo. El Dev no lo implementó.

PROBLEMA 2 — ORDEN DE DECLARACIÓN vs. USO (Riesgo de hoisting): `enableAnalytics()` se declara ANTES de las funciones init*, lo cual es correcto para que initCookieBanner pueda referenciarla. Sin embargo, la directiva del Tech Lead en PASO 4 indica explícitamente: 'Declárala en el scope del DOMContentLoaded listener, ANTES de las llamadas init*'. El Dev la declaró antes de initRouter (correcto en posición), pero la directiva también dice que debe estar antes de las funciones init*, no intercalada con ellas. En este caso el hoisting de function declarations en JS resuelve el problema en runtime, pero el orden de declaración no sigue la estructura mandada por el Tech Lead (enableAnalytics debería estar declarada justo antes del bloque de arranque, no al inicio del listener). Este es un defecto menor de estructura pero viola la directiva de orden.

PROBLEMA 3 — initCookieBanner NO reactiva analytics en visita recurrente con consentimiento previo: Como consecuencia directa del Problema 1, el flujo end-to-end falla: Usuario acepta cookies (visita 1) → recarga página (visita 2) → initCookieBanner detecta 'accepted', oculta banner y RETORNA sin llamar enableAnalytics(). initAnalyticsStub() lo rescata, pero esto es un workaround no intencional, no el diseño correcto. El contrato de comportamiento del PASO 4 es explícito y no fue respetado.

